using System.Runtime.CompilerServices;
using DeskCanvas.Core;

internal static class V29LegacyImportContractTests
{
    [ModuleInitializer] internal static void Run() { Case("merge preserves current and imports media", Merge); Case("rerun and built-ins deduplicate", Rerun); Case("Codex usage imports and deduplicates", CodexUsage); Case("ID and media collisions repair", Collisions); Case("file selection and failures are safe", Failures); }
    private static void Merge() => InTemp((source, destination) => { Write(source, new CanvasItem { Id = Guid.Parse("11111111-1111-1111-1111-111111111111"), ContentKind = CanvasContentKinds.Image, StoredFileName = "old.png" }); File.WriteAllText(Path.Combine(source, "Media", "old.png"), "old"); var result = LegacyLayoutImportService.Import(source, destination, [new CanvasItem { ContentKind = CanvasContentKinds.Clock }]); Equal(1, result.Items.Count); Equal("old.png", result.Items.Single().StoredFileName); Equal(true, File.Exists(Path.Combine(destination, "Media", "old.png"))); });
    private static void Rerun() => InTemp((source, destination) => { Write(source, new CanvasItem { ContentKind = CanvasContentKinds.Image, StoredFileName = "same.png" }, new CanvasItem { ContentKind = CanvasContentKinds.Clock }); File.WriteAllText(Path.Combine(source, "Media", "same.png"), "same"); var first = LegacyLayoutImportService.Import(source, destination, []); var second = LegacyLayoutImportService.Import(source, destination, first.Items); Equal(0, second.Items.Count); Equal(2, second.SkippedDuplicate); });
    private static void CodexUsage() => InTemp((source, destination) => { Write(source, new CanvasItem { ContentKind = CanvasContentKinds.CodexUsage, DisplayName = "Codexリミット" }); var first = LegacyLayoutImportService.Import(source, destination, []); Equal(1, first.Items.Count); Equal(CanvasContentKinds.CodexUsage, first.Items.Single().ContentKind); var second = LegacyLayoutImportService.Import(source, destination, first.Items); Equal(0, second.Items.Count); Equal(1, second.SkippedDuplicate); });
    private static void Collisions() => InTemp((source, destination) => { var id = Guid.Parse("33333333-3333-3333-3333-333333333333"); Write(source, new CanvasItem { Id = id, ContentKind = CanvasContentKinds.Image, StoredFileName = "same.png" }); File.WriteAllText(Path.Combine(source, "Media", "same.png"), "legacy"); Directory.CreateDirectory(Path.Combine(destination, "Media")); File.WriteAllText(Path.Combine(destination, "Media", "same.png"), "current"); var result = LegacyLayoutImportService.Import(source, destination, [new CanvasItem { Id = id, ContentKind = CanvasContentKinds.Image, StoredFileName = "current.png" }]); Equal(1, result.Items.Count); Equal(false, result.Items.Single().Id == id); Equal("same-legacy-1.png", result.Items.Single().StoredFileName); });
    private static void Failures() => InTemp((source, destination) => { Write(source, new CanvasItem { ContentKind = CanvasContentKinds.Image, StoredFileName = "gone.png" }); Equal(1, LegacyLayoutImportService.Import(source, destination, []).MissingMedia); Equal(true, LegacyLayoutImportService.Import(destination, destination, []).IsRejected); File.WriteAllText(Path.Combine(source, "backup.json"), "{\"Items\":[]}"); Equal(0, LegacyLayoutImportService.Import(Path.Combine(source, "backup.json"), destination, []).Items.Count); File.WriteAllText(Path.Combine(source, "layout.json"), "{broken"); Equal(true, LegacyLayoutImportService.Import(source, destination, []).IsRejected); });
    private static void Write(string root, params CanvasItem[] items) { Directory.CreateDirectory(Path.Combine(root, "Media")); new LayoutRepository(root).Save(new CanvasLayout { Items = items.ToList() }); }
    private static void InTemp(Action<string, string> action) { var root = Path.Combine(Path.GetTempPath(), "DeskCanvasImportTests", Guid.NewGuid().ToString("N")); var source = Path.Combine(root, "legacy"); var destination = Path.Combine(root, "current"); Directory.CreateDirectory(source); Directory.CreateDirectory(destination); try { action(source, destination); } finally { Directory.Delete(root, true); } }
    private static void Case(string name, Action test) { test(); Console.WriteLine($"PASS v1.2 import {name}"); } private static void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new InvalidOperationException($"expected={expected}, actual={actual}"); }
}
